/* Gzip-compressed pinned offline POE2 metadata; see TRADE_COVERAGE.md. */
(function(root){const encoded="";function install(snapshot){function extend(data){data.extended=true;data.catalog=snapshot;const oldCategories=data.categories;data.categories=snapshot.categories.map(c=>({...c,aliases:[...new Set([...c.aliases,...(oldCategories.find(o=>o.id===c.id)?.aliases||[])])]}));data.uniqueEligibility=snapshot.uniqueEligibility;data.properties={...data.properties,...snapshot.properties};for(const [cat,ids] of Object.entries(snapshot.eligibility))data.eligibility[cat]=[...new Set([...(data.eligibility[cat]||[]),...ids])];const byId=new Map(data.stats.map(s=>[s.id,s]));for(const s of snapshot.stats)byId.set(s.id,{...byId.get(s.id),...s});data.stats=[...byId.values()].filter(s=>!snapshot.unsupportedStatIds.includes(s.id));for(const d of snapshot.fields)if(!data.curated.some(x=>x.key===d.key))data.curated.push(d);return data;}return{snapshot,extend};}if(typeof module!=='undefined'&&module.exports){module.exports=install(JSON.parse(require('node:zlib').gunzipSync(Buffer.from(encoded,'base64')).toString('utf8')));}else{root.TradeCatalogReady=(async()=>{if(typeof DecompressionStream==='undefined')throw Error('아이템 자료를 열려면 최신 브라우저가 필요해요.');const bytes=Uint8Array.from(atob(encoded),c=>c.charCodeAt(0));const text=await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).text();install(JSON.parse(text)).extend(root.TradeData);})();}})(typeof window!=='undefined'?window:globalThis);
